-- The HELIFACE code key (Code keys -> Parting -> HELIFACE), from the ISCAR
-- e-catalog's HELIFACE families (HFPR/L, HFPN inserts and HFA/HGA adapters,
-- HFF blades, HFH/HGH holders, HFI bars); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.heliface', $ck${"title": "HELIFACE code key – inserts and tools", "subtitle": "Utility double-ended face machining inserts (HFPR/L, HFPN) and face grooving adapters, blades, holders, bars and cartridges", "example": "HFAIR 140C-4T30DG", "decoder": "heliface", "sections": [{"key": "i-family", "title": "Insert – family", "rows": [{"code": "HFP", "meaning": "Utility double-ended face machining insert (HFPR / HFPL / HFPN)"}]}, {"key": "i-hand", "title": "Insert – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "N", "meaning": "Neutral (HFPN, for HFFH / HFFA blades)"}]}, {"key": "i-width", "title": "Insert – width and corner radius", "rows": [{"code": "####", "meaning": "Width (first digit) and corner radius x10 (e.g. 4004 = 4 mm, R0.4; 4020 = 4 mm, R2.0 full radius)"}]}, {"key": "t-prefix", "title": "Tool – prefix", "rows": [{"code": "IM40 / IM50", "meaning": "ISO 26622-1 tapered shank size (IM40 HFIR-MC)"}, {"code": "CR", "meaning": "Cartridge for face grooving and turning (CR HFIR-16M)"}, {"code": "IH", "meaning": "Intermediate serrated cartridge for standard HFAIR / HFPAD adapters"}]}, {"key": "t-family", "title": "Tool – family", "sample": "HFAI", "rows": [{"code": "HFAI", "meaning": "Adapters for internal face grooving and turning"}, {"code": "HFAE", "meaning": "Adapters for external facing along shafts"}, {"code": "HGAI", "meaning": "Adapters for internal face grooving and turning, 3 mm GRIP inserts"}, {"code": "HGAE", "meaning": "Adapters for external facing along shafts, 3 mm GRIP inserts"}, {"code": "HFF", "meaning": "Blades for face machining (HFFR / HFFL)"}, {"code": "HFFH", "meaning": "Face grooving blades (HFPN inserts)"}, {"code": "HFFA", "meaning": "Reinforced face grooving blades (HFPN inserts)"}, {"code": "HFH", "meaning": "Integral holders for facing; HFHR/L-M for shallow face grooving"}, {"code": "HFHP", "meaning": "Perpendicular toolholders for shallow face grooving"}, {"code": "HGH", "meaning": "Integral holders for face grooving and turning, GRIP inserts"}, {"code": "HFI", "meaning": "Boring bars for internal grooving and turning (HFIR/L-MC)"}, {"code": "HFPAD", "meaning": "Adapter carrying the IH-HFPAD intermediate cartridge"}]}, {"key": "t-hand", "title": "Tool – hand", "sample": "R", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank / bar size in mm (e.g. 20, 25)"}, {"code": "####", "meaning": "Shank height x width (e.g. 1212 = 12 x 12 mm)"}]}, {"key": "t-dmin", "title": "Tool – minimum face groove diameter", "sample": "140", "rows": [{"code": "##", "meaning": "Minimum penetration diameter DAXN in mm (e.g. 25)"}, {"code": "###", "meaning": "Minimum penetration diameter DAXN in mm (e.g. 140)"}]}, {"key": "t-width", "title": "Tool – insert width", "sample": "4", "rows": [{"code": "#", "meaning": "Insert / cutting width in mm (e.g. 3, 4, 5, 6)"}]}, {"key": "t-depth", "title": "Tool – maximum cutting depth", "sample": "T30", "rows": [{"code": "T##", "meaning": "Maximum cutting depth in mm (e.g. T30 = 30 mm)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "sample": "C", "rows": [{"code": "C", "meaning": "With coolant supply"}, {"code": "DG", "meaning": "For DO-GRIP inserts (DGN)"}, {"code": "M", "meaning": "Shallow face grooving, several insert widths (min.–max. cutting width)"}, {"code": "MC", "meaning": "Boring bar with coolant, several insert widths"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
